import './polyfills'

import { createApp, defineAsyncComponent } from 'vue'
import { createHead, VueHeadMixin } from '@unhead/vue/client'
import { sync } from 'vuex-router-sync'

import 'bulma/css/bulma.css'

import App from '@/App.vue'
import i18n from '@/lib/i18n'
import resizableColumn from '@/directives/resizable-column'
import router from '@/router'
import store from '@/store'
import { setupChunkErrorHandler } from '@/lib/chunk-error'

import vAutosize from '@/directives/autosize'
import VueWebsocket from 'vue-websocket-next'
import IO from 'socket.io-client'
import VueAnimXYZ from '@animxyz/vue3'
import '@animxyz/core'

const app = createApp(App)
const head = createHead()

app.use(i18n)
app.use(head)
app.mixin(VueHeadMixin)
app.use(router)
app.use(store)
app.use(resizableColumn)
app.use(VueWebsocket.default || VueWebsocket, IO, '/events')
app.directive('autosize', vAutosize)
app.use(VueAnimXYZ)

// chart.js weighs ~90 kB gzipped and only a handful of screens draw a chart:
// registering the tags lazily keeps it out of the initial payload.
const chartTags = [
  'line-chart',
  'pie-chart',
  'column-chart',
  'bar-chart',
  'area-chart',
  'scatter-chart',
  'geo-chart',
  'timeline'
]
chartTags.forEach(name =>
  app.component(
    name,
    defineAsyncComponent(
      async () => (await import('@/lib/chartkick')).default[name]
    )
  )
)

// Make the current route part of the main state.
sync(store, router)

// Global custom directive to enable automatic focus on field after page loading.
app.directive('focus', {
  mounted(el, binding) {
    el.focus(binding.value)
  }
})

// Inject the socket into the store.
store.$socket = app.config.globalProperties.$socket

// Last-resort error logging: Sentry only runs in production builds, and
// without these handlers dev/self-hosted errors vanish silently.
app.config.errorHandler = (err, instance, info) => {
  console.error(`Vue error in ${info}:`, err)
}
window.addEventListener('unhandledrejection', event => {
  console.error('Unhandled promise rejection:', event.reason)
})

setupChunkErrorHandler(router)

app.mount('#app')
